algorithms.pseudocode:
function IS_CONTRACTIBLE(carrier):
    pts <- distinct elements of carrier   # preserve first occurrence
    return (length(pts) == 1)

function CENTER(carrier):
    assert IS_CONTRACTIBLE(carrier)
    return carrier[0]

function HOMOTOPY_FIBER(f, domain, b):
    return [ a in domain : f(a) == b ]

function IS_EQUIVALENCE(f, domain, codomain):
    for b in codomain:
        fib <- HOMOTOPY_FIBER(f, domain, b)
        if number_of_distinct(fib) != 1:   # fibre not contractible
            return False
    return True
